     "lang": "python",
     "code": "# 251: Fibonacci with matrix exponentiation\ndef fib_matrix(n):\n    def mat_mul(A, B):\n        return [[A[0][0]*B[0][0]+A[0][1]*B[1][0], A[0][0]*B[0][1]+A[0][1]*B[1][1]],\n                [A[1][0]*B[0][0]+A[1][1]*B[1][0], A[1][0]*B[0][1]+A[1][1]*B[1][1]]]\n    def mat_pow(M, p):\n        if p == 1:\n            return M\n        if p % 2 == 0:\n            half = mat_pow(M, p // 2)\n            return mat_mul(half, half)\n        return mat_mul(M, mat_pow(M, p - 1))\n    if n <= 1:\n        return n\n    result = mat_pow([[1,1],[1,0]], n)\n    return result[0][1]\nprint(fib_matrix(50))\n\n# 252: Miller-Rabin primality test\ndef is_prime_miller(n, k=10):\n    if n < 2:\n        return False\n    if n < 4:\n        return True\n    if n % 2 == 0:\n        return False\n    d = n - 1\n    r = 0\n    while d % 2 == 0:\n        d //= 2\n        r += 1\n    for _ in range(k):\n        a = random.randrange(2, n - 1)\n        x = pow(a, d, n)\n        if x in (1, n - 1):\n            continue\n        for _ in range(r - 1):\n            x = pow(x, 2, n)\n            if x == n - 1:\n                break\n        else:\n            return False\n    return True\nprint(is_prime_miller(1000000007))  # True\n\n# 253: Pollard's Rho factorization\ndef pollard_rho(n):\n    if n % 2 == 0:\n        return 2\n    x = random.randint(2, n - 1)\n    y = x\n    c = random.randint(1, n - 1)\n    d = 1\n    while d == 1:\n        x = (x * x + c) % n\n        y = (y * y + c) % n\n        y = (y * y + c) % n\n        d = math.gcd(abs(x - y), n)\n    return d if d != n else None\nprint(pollard_rho(91))  # 7 or 13\n\n# 254: Chinese remainder theorem\ndef chinese_remainder(remainders, moduli):\n    N = 1\n    for m in moduli:\n        N *= m\n    result = 0\n    for r, m in zip(remainders, moduli):\n        ni = N // m\n        _, xi, _ = extended_gcd(ni % m, m)\n        result += r * xi * ni\n    return result % N\nprint(chinese_remainder([2, 3, 2], [3, 5, 7]))  # 23\n\n# 255: Fast Fourier Transform (simplified)\ndef fft(x):\n    n = len(x)\n    if n == 1:\n        return x\n    even = fft(x[0::2])\n    odd = fft(x[1::2])\n    T = [math.e**(-2j*math.pi*k/n) * odd[k] for k in range(n//2)]\n    return [even[k] + T[k] for k in range(n//2)] + [even[k] - T[k] for k in range(n//2)]\n# Pad to power of 2\nsignal = [1, 1, 1, 1, 0, 0, 0, 0]\nresult = fft(signal)\nprint([round(abs(x), 2) for x in result])\n\n# 256: Catalan number\ndef catalan(n):\n    return comb(2*n, n) // (n + 1)\nprint([catalan(i) for i in range(10)])\n\n# 257: Euler's totient\ndef euler_totient(n):\n    result = n\n    p = 2\n    while p * p <= n:\n        if n % p == 0:\n            while n % p == 0:\n                n //= p\n            result -= result // p\n        p += 1\n    if n > 1:\n        result -= result // n\n    return result\nprint(euler_totient(12))  # 4\n\n# 258: Sieve of Euler totient\ndef totient_sieve(n):\n    phi = list(range(n + 1))\n    for i in range(2, n + 1):\n        if phi[i] == i:  # i is prime\n            for j in range(i, n + 1, i):\n                phi[j] -= phi[j] // i\n    return phi\nprint(totient_sieve(20))\n\n# 259: Number of divisors\ndef count_divisors(n):\n    count = 0\n    i = 1\n    while i * i <= n:\n        if n % i == 0:\n            count += 2 if i != n // i else 1\n        i += 1\n    return count\nprint(count_divisors(36))  # 9\n\n# 260: Sum of divisors\ndef sum_divisors(n):\n    total = 0\n    i = 1\n    while i * i <= n:\n        if n % i == 0:\n            total += i\n            if i != n // i:\n                total += n // i\n        i += 1\n    return total\nprint(sum_divisors(12))  # 28",
