     "code": "def multi_sort(data, keys, reverse_flags=None):\n    if reverse_flags is None:\n        reverse_flags = [False] * len(keys)\n    from functools import cmp_to_key\n    def compare(a, b):\n        for key, rev in zip(keys, reverse_flags):\n            va, vb = a[key], b[key]\n            if va < vb:\n                return 1 if rev else -1\n            if va > vb:\n                return -1 if rev else 1\n        return 0\n    return sorted(data, key=cmp_to_key(compare))\n\ndata = [{\"name\": \"Charlie\", \"age\": 30}, {\"name\": \"Alice\", \"age\": 30}, {\"name\": \"Bob\", \"age\": 25}]\nprint(multi_sort(data, [\"age\", \"name\"], [True, False]))",
