     "t": "code",
     "lang": "python",
     "code": "# 341: Configuration parser\ndef parse_config(text):\n    config = {}\n    current_section = None\n    for line in text.strip().split('\\n'):\n        line = line.strip()\n        if not line or line.startswith('#'):\n            continue\n        if line.startswith('[') and line.endswith(']'):\n            current_section = line[1:-1]\n            config[current_section] = {}\n        elif '=' in line:\n            key, value = line.split('=', 1)\n            key = key.strip()\n            value = value.strip()\n            # Type coercion\n            if value.lower() in ('true', 'false'):\n                value = value.lower() == 'true'\n            elif value.isdigit():\n                value = int(value)\n            else:\n                try:\n                    value = float(value)\n                except ValueError:\n                    pass\n            if current_section:\n                config[current_section][key] = value\n            else:\n                config[key] = value\n    return config\n\nini = \"\"\"\n[database]\nhost = localhost\nport = 5432\ndebug = true\n\n[app]\nname = MyApp\nversion = 1.0\n\"\"\"\nprint(parse_config(ini))\n\n# 342: Environment variable manager\ndef env_manager(env_text):\n    env = {}\n    for line in env_text.strip().split('\\n'):\n        line = line.strip()\n        if not line or line.startswith('#'):\n            continue\n        if '=' in line:\n            key, value = line.split('=', 1)\n            value = value.strip().strip('\"').strip(\"'\")\n            env[key.strip()] = value\n    return env\n\nenv = \"\"\"\n# Database config\nDB_HOST=localhost\nDB_PORT=\"5432\"\nSECRET_KEY='my-secret'\n\"\"\"\nprint(env_manager(env))\n\n# 343: Command-line argument parser\ndef parse_args(args):\n    parsed = {\"flags\": [], \"options\": {}, \"positional\": []}\n    i = 0\n    while i < len(args):\n        arg = args[i]\n        if arg.startswith('--'):\n            if '=' in arg:\n                key, value = arg[2:].split('=', 1)\n                parsed[\"options\"][key] = value\n            elif i + 1 < len(args) and not args[i+1].startswith('-'):\n                parsed[\"options\"][arg[2:]] = args[i+1]\n                i += 1\n            else:\n                parsed[\"flags\"].append(arg[2:])\n        elif arg.startswith('-'):\n            parsed[\"flags\"].extend(list(arg[1:]))\n        else:\n            parsed[\"positional\"].append(arg)\n        i += 1\n    return parsed\n\nprint(parse_args([\"--name=test\", \"-v\", \"--port\", \"8080\", \"input.txt\"]))\n\n# 344: JSON path query\ndef json_path(data, path):\n    parts = path.strip('.').split('.')\n    current = data\n    for part in parts:\n        if part.endswith(']'):\n            key, idx = part[:-1].split('[')\n            current = current[key][int(idx)]\n        elif isinstance(current, dict):\n            current = current.get(part)\n        elif isinstance(current, list) and part.isdigit():\n            current = current[int(part)]\n        else:\n            return None\n        if current is None:\n            return None\n    return current\n\ndata = {\"users\": [{\"name\": \"Alice\", \"address\": {\"city\": \"NYC\"}}, {\"name\": \"Bob\"}]}\nprint(json_path(data, \"users[0].address.city\"))  # NYC\n\n# 345: Deep equality check\ndef deep_equal(a, b):\n    if type(a) != type(b):\n        return False\n    if isinstance(a, dict):\n        if set(a.keys()) != set(b.keys()):\n            return False\n        return all(deep_equal(a[k], b[k]) for k in a)\n    if isinstance(a, (list, tuple)):\n        if len(a) != len(b):\n            return False\n        return all(deep_equal(x, y) for x, y in zip(a, b))\n    return a == b\n\nprint(deep_equal({\"a\": [1, {\"b\": 2}]}, {\"a\": [1, {\"b\": 2}]}))  # True\nprint(deep_equal({\"a\": [1, {\"b\": 2}]}, {\"a\": [1, {\"b\": 3}]}))  # False\n\n# 346: Deep copy\ndef deep_copy(obj):\n    if isinstance(obj, dict):\n        return {k: deep_copy(v) for k, v in obj.items()}\n    if isinstance(obj, list):\n        return [deep_copy(item) for item in obj]\n    if isinstance(obj, tuple):\n        return tuple(deep_copy(item) for item in obj)\n    if isinstance(obj, set):\n        return {deep_copy(item) for item in obj}\n    return obj\n\noriginal = {\"a\": [1, 2, {\"b\": 3}]}\ncopy = deep_copy(original)\ncopy[\"a\"][2][\"b\"] = 99\nprint(f\"Original: {original}, Copy: {copy}\")\n\n# 347: Function pipeline with error handling\ndef safe_pipeline(data, *functions):\n    errors = []\n    for func in functions:\n        try:\n            data = func(data)\n        except Exception as e:\n            errors.append({\"function\": func.__name__, \"error\": str(e)})\n            break\n    return {\"result\": data, \"errors\": errors}\n\ndef double(x): return x * 2\ndef add_ten(x): return x + 10\ndef divide_by_zero(x): return x / 0\n\nprint(safe_pipeline(5, double, add_ten))\nprint(safe_pipeline(5, double, divide_by_zero, add_ten))\n\n# 348: Rate limiter (functional)\nimport time\n\ndef create_rate_limiter(max_calls, period_seconds):\n    calls = []\n    def is_allowed():\n        now = time.time()\n        # Remove old calls\n        while calls and calls[0] < now - period_seconds:\n            calls.pop(0)\n        if len(calls) < max_calls:\n            calls.append(now)\n            return True\n        return False\n    return is_allowed\n\nlimiter = create_rate_limiter(3, 1.0)\nprint(limiter())  # True\nprint(limiter())  # True\nprint(limiter())  # True\nprint(limiter())  # False (exceeded)\n\n# 349: Circuit breaker (functional)\ndef create_circuit_breaker(failure_threshold=3, reset_timeout=10):\n    state = {\"failures\": 0, \"last_failure\": 0, \"is_open\": False}\n    def execute(func, *args, **kwargs):\n        if state[\"is_open\"]:\n            if time.time() - state[\"last_failure\"] > reset_timeout:\n                state[\"is_open\"] = False\n                state[\"failures\"] = 0\n            else:\n                return {\"success\": False, \"error\": \"Circuit is OPEN\"}\n        try:\n            result = func(*args, **kwargs)\n            state[\"failures\"] = 0\n            return {\"success\": True, \"result\": result}\n        except Exception as e:\n            state[\"failures\"] += 1\n            state[\"last_failure\"] = time.time()\n            if state[\"failures\"] >= failure_threshold:\n                state[\"is_open\"] = True\n            return {\"success\": False, \"error\": str(e)}\n    return execute\n\ncb = create_circuit_breaker(2)\nprint(cb(lambda: 42))\nprint(cb(lambda: 1/0))\nprint(cb(lambda: 1/0))\nprint(cb(lambda: 42))  # Circuit open\n\n# 350: Event emitter (functional)\ndef create_event_emitter():\n    listeners = {}\n    def on(event, callback):\n        listeners.setdefault(event, []).append(callback)\n    def emit(event, *args, **kwargs):\n        results = []\n        for cb in listeners.get(event, []):\n            results.append(cb(*args, **kwargs))\n        return results\n    def off(event, callback=None):\n        if callback:\n            listeners[event] = [cb for cb in listeners.get(event, []) if cb != callback]\n        else:\n            listeners.pop(event, None)\n    return {\"on\": on, \"emit\": emit, \"off\": off}\n\nemitter = create_event_emitter()\nemitter[\"on\"](\"data\", lambda x: print(f\"Got: {x}\"))\nemitter[\"on\"](\"data\", lambda x: x * 2)\nresults = emitter[\"emit\"](\"data\", 42)\nprint(f\"Results: {results}\")",
