     "code": "def validate_json_schema(data, schema):\n    errors = []\n    def validate(data, schema, path=\"root\"):\n        schema_type = schema.get(\"type\")\n        if schema_type == \"object\":\n            if not isinstance(data, dict):\n                errors.append(f\"{path}: expected object, got {type(data).__name__}\")\n                return\n            for field, field_schema in schema.get(\"properties\", {}).items():\n                if field in schema.get(\"required\", []) and field not in data:\n                    errors.append(f\"{path}.{field}: required field missing\")\n                elif field in data:\n                    validate(data[field], field_schema, f\"{path}.{field}\")\n        elif schema_type == \"array\":\n            if not isinstance(data, list):\n                errors.append(f\"{path}: expected array\")\n                return\n            for i, item in enumerate(data):\n                validate(item, schema.get(\"items\", {}), f\"{path}[{i}]\")\n        elif schema_type == \"string\":\n            if not isinstance(data, str):\n                errors.append(f\"{path}: expected string\")\n        elif schema_type == \"number\":\n            if not isinstance(data, (int, float)):\n                errors.append(f\"{path}: expected number\")\n            if \"minimum\" in schema and data < schema[\"minimum\"]:\n                errors.append(f\"{path}: value {data} < minimum {schema['minimum']}\")\n    validate(data, schema)\n    return {\"valid\": len(errors) == 0, \"errors\": errors}\n\nschema = {\n    \"type\": \"object\",\n    \"required\": [\"name\", \"age\"],\n    \"properties\": {\n        \"name\": {\"type\": \"string\"},\n        \"age\": {\"type\": \"number\", \"minimum\": 0},\n        \"tags\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}}\n    }\n}\nprint(validate_json_schema({\"name\": \"Alice\", \"age\": 30, \"tags\": [\"dev\"]}, schema))\nprint(validate_json_schema({\"name\": 123, \"tags\": [1, 2]}, schema))",
